WITH ValidAccounts AS (SELECT *, CASE WHEN status IN ('OPEN', 'CLOSED') THEN 'Group A' ELSE 'Other' END status_group FROM accounts WHERE status = 'OPEN' AND balance BETWEEN 64000 AND 78000), accounts_stats AS (SELECT account_type, SUM(balance) total_balance FROM ValidAccounts GROUP BY account_type) SELECT account_type, total_balance FROM accounts_stats ORDER BY account_type, total_balance DESC;
